// Valida secret, honeypot, rate limit por IP e normaliza o pedido
const item = $input.first().json;
const h = item.headers || {};
const b = item.body || {};

if (!$env.WEBHOOK_SECRET || h['x-webhook-secret'] !== $env.WEBHOOK_SECRET) return [];
if (b.site) return []; // honeypot preenchido = bot

// rate limit simples: 5 pedidos por IP a cada 10 min (só persiste em execução de produção)
const ip = String(h['x-forwarded-for'] || h['x-real-ip'] || '').split(',')[0].trim() || 'sem-ip';
const st = $getWorkflowStaticData('global');
const agora = Date.now(), janela = 10 * 60 * 1000;
st.rl = Object.fromEntries(Object.entries(st.rl || {}).map(([k, v]) => [k, v.filter(t => agora - t < janela)]).filter(([, v]) => v.length));
const hits = st.rl[ip] || [];
if (hits.length >= 5) return [];
st.rl[ip] = [...hits, agora];

const limpa = (v, max = 120) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

let tel = String(b.whatsapp || '').replace(/\D/g, '');
if (tel.startsWith('55') && tel.length >= 12) tel = tel.slice(2);
tel = tel.length === 10 || tel.length === 11 ? '55' + tel : '';

const itens = (Array.isArray(b.itens) ? b.itens : [])
  .map(i => ({ produto: limpa(i && i.produto), quantidade: Math.min(999, Math.max(1, parseInt(i && i.quantidade, 10) || 1)) }))
  .filter(i => i.produto)
  .slice(0, 10);

const utms = {};
for (const [k, v] of Object.entries(b.utms || b)) if (k.startsWith('utm_')) utms[k] = limpa(v, 200);

const itensHash = JSON.stringify([...itens].sort((a, c) => a.produto.localeCompare(c.produto)));

return [{ json: {
  nome: limpa(b.nome, 80),
  telefone: tel,
  empresa: limpa(b.empresa),
  cidade: limpa(b.cidade),
  prazo: limpa(b.prazo, 40),
  itens,
  itens_hash: itensHash,
  origem: limpa(b.origem, 40) || 'desconhecida',
  utms,
  ip,
} }];

// Monta os textos do aviso para o Daniel e da confirmação para o cliente
const l = $input.first().json;
const itens = typeof l.itens === 'string' ? JSON.parse(l.itens) : (l.itens || []);
const listaItens = itens.length ? itens.map(i => '• ' + i.quantidade + 'x ' + i.produto).join('\n') : '• (clicou no botão geral, sem item)';
const urgente = l.prazo === 'Preciso logo';

const linhas = [
  (urgente ? '🔥 URGENTE\n' : '') + '🛒 *Novo pedido pela landing*',
  '',
  listaItens,
  '',
  '👤 ' + (l.nome || 'Sem nome'),
  l.empresa ? '🏢 ' + l.empresa : null,
  l.cidade ? '📍 ' + l.cidade : null,
  l.prazo ? '⏱️ Prazo: ' + l.prazo : null,
  '🔗 Origem: ' + l.origem,
  l.telefone ? '📱 https://wa.me/' + l.telefone : '📱 Cliente não deixou o WhatsApp (ele deve te chamar direto)',
].filter(v => v !== null);

const itensCurto = itens.map(i => i.quantidade + 'x ' + i.produto).join(', ');
const primeiroNome = (l.nome || '').split(' ')[0] || 'tudo bem';

return [{ json: {
  id: l.id,
  telefone: l.telefone,
  msgDaniel: linhas.join('\n'),
  msgCliente: 'Oi ' + primeiroNome + ', recebemos seu pedido na Bem Estar: ' + (itensCurto || 'orçamento') + '. O Daniel já vai te responder por aqui.',
} }];
